\u007a\u0042\u0039\u0073\u0070\u004b\u003a\u0038\u0039\u002c\u007d\u007b\u002b\u0021\u0079\u002f\u0034\u0037\u0024\u0068\u0060\u002c\u006e\u005e\u0074\u0029\u0054\u007a\u005c\u0023\u0028\u0020\u003e\u0022\u0041\u0068\u0036\u0078\u003c\u003c\u0043\u003b\u0049\u0025\u002d\u0056\u005b\u002e\u0055\u0025\u0042\u0053\u0032\u0045\u0061\u0046\u0054\u0034\u006c\u0020\u006f\u002f\u0065\u0023\u0033\u0025\u007a\u007c\u005c\u0079\u0030\u0076\u0043\u003f\u004d\u004a\u0056\u004b\u005e\u003b\u003e\u005d\u0026\u0039\u0023\u0047\u002f\u0045\u006f\u0061\u007a\u0053\u0046\u005c\u0048\u0023\u0070\u003a\u003c\u0020\u006b\u0049\u0073\u0052\u0066\u005c\u0034\u0032\u0027\u0025\u0044\u0022\u0026\u0065\u006b\u0040\u0071\u007a\u0055\u004f\u006f\u004e\u005c\u0059\u0060\u007e\u0052\u0048\u004c\u004b\u0066\u0038\u0050\u0062\u004d\u002e\u005e\u0068\u002b\u0047\u0052\u005b\u0060\u007c\u005a\u0067\u0039\u005a\u0071\u005c\u005f\u006a\u004f\u0053\u002e\u0076\u0073\u002e\u005c\u0062\u0030\u0064\u0061\u0070\u0051\u004e\u0058\u0025\u004c\u0025\u0024\u0070\u002d\u006b\u0058\u0033\u0032\u0078\u006a\u007c\u004a\u0040\u0027\u003a\u0058\u0021\u0051\u0046\u0049\u0061\u0073\u003e\u0072\u005f\u0052\u005f\u004c\u004d\u0037\u0071\u0074\u006b\u0062\u0039\u0042\u0070\u0079\u0044\u0076\u005a\u003d\u0042\u0048\u0029\u002c\u007d\u0043\u0073\u004f\u004d\u003c\u007c\u002d\u004d\u0022\u0074\u0029\u005a\u0077\u007b\u007d\u0055\u0073\u006d\u003b\u002a\u0041\u006d\u0058\u0050\u003e\u005b\u0052\u0049\u003b\u004a\u0029\u0021\u006c\u0027\u0051\u0063\u005e\u0053\u0042\u0022\u0038\u0024\u0026\u0079\u002b\u0066\u0057\u0061\u0072\u0040\u004e\u0079\u0059\u004a\u0064\u003d\u003c\u007b\u005d\u0027\u0072\u0030\u0020\u004d\u0076\u0030\u0021\u003f\u0027\u0028\u005e\u0069\u005b\u0044\u0025\u0043\u003d\u005a\u003d\u0068\u005d\u0022\u004d\u002b\u0031\u0049\u0039\u006f\u0066\u004f\u0059\u005d\u0038\u004a\u0053\u0029\u007a\u0022\u0056\u006b\u0074\u005d\u0054\u0049\u003e\u0060\u006c\u0053\u005b\u0043\u006b\u0028\u0047\u0061\u006f\u0039\u0049\u0035\u0066\u0051\u002a\u0033\u0067\u0044\u0070\u0053\u0052\u0071\u0021\u004f\u007b\u0041\u0058\u005c\u0059\u006e\u0026\u0046\u007b\u0039\u0030\u006b\u0070\u006c\u004f\u0058\u0043\u0057\u004f\u005e\u0071\u0043\u0076\u0023\u0024\u0036\u007c\u0071\u0033\u005c\u002e\u003d\u0054\u0053\u0058\u0049\u0058\u0024\u004d\u0078\u0058\u0037\u0041\u0055\u0062\u0053\u0038\u0031\u0058\u005f\u0058\u0047\u002a\u005c\u0068\u007a\u006f\u004e\u006b\u0070\u0028\u003e\u005d\u0025\u0073\u0076\u0032\u0066\u0040\u007b\u0069\u0061\u002a\u0033\u005a\u0033\u0021\u0034\u002a\u002d\u0044\u002a\u0023\u005f\u0056\u004c\u006d\u005a\u0076\u005f\u005c\u0064\u0072\u003f\u0046\u0035\u0063\u004e\u0079\u003e\u0049\u0069\u0021\u002d\u0034\u0030\u0053\u0051\u0054\u0049\u0025\u0035\u0040\u003a\u006b\u007b\u0032\u004e\u0045\u0056\u0043\u003d\u0048\u0025\u002c\u002d\u0052\u005f\u002e\u0037\u003c\u0076\u0075\u007e\u0036\u0041\u005e\u005f\u0078\u0051\u005c\u0051\u0050\u0069\u0051\u0046\u0062\u0074\u005b\u0021\u006a\u0028\u005d\u0043\u0023\u0021\u002e\u0040\u0057\u004b\u005a\u0028\u004e\u004e\u006d\u0068\u003c\u0033\u0033\u003b\u0025\u0047\u0076\u0073\u0069\u0060\u003a\u007b\u0052\u005c\u006d\u006e\u005d\u006f\u004d\u0022\u0057\u0052\u0076\u003a\u0021\u0051\u0034\u0022\u004b\u0037\u0029\u003e\u004a\u003b\u0064\u0030\u0069\u0068\u0032\u002e\u0024\u0063\u0038\u006f\u007b\u0064\u0039\u005e\u0073\u0075\u0069\u006d\u0069\u0078\u0034\u0050\u005c\u0065\u0022\u005e\u0061\u0022\u005e\u0024\u002d\u0046\u0078\u0036\u0068\u006c\u0076\u0074\u003a\u007b\u002d\u003c\u004a\u0078\u0061\u0039\u003e\u0043\u0058\u0062\u003e\u0073\u002a\u0045\u0056\u0039\u004f\u002c\u003d\u0056\u0041\u004f\u0021\u0079\u005f\u0020\u002d\u004c\u007a\u0050\u002b\u0040\u0077\u0033\u0052\u0066\u0052\u002a\u002c\u0060\u006b\u003a\u004c\u0020\u0077\u0056\u0066\u0024\u005a\u0031\u0040\u007a\u0063\u0074\u0056\u0039\u0048\u0056\u0052\u0059\u004b\u0048\u0034\u0035\u0077\u0073\u002a\u002a\u0059\u007b\u0030\u003d\u0047\u003d\u003c\u0066\u0063\u005f\u0062\u0030\u0054\u004e\u0024\u0056\u0077\u007a\u0046\u0055\u004b\u0039\u0070\u0060\u0051\u006b\u0021\u0062\u005d\u003f\u0047\u0044\u0028\u0021\u005c\u0021\u0078\u0026\u006f\u005d\u0075\u0048\u0072\u0052\u0028\u006e\u0060\u0072\u004e\u0026\u0070\u004d\u0075\u0060\u005f\u0055\u0059\u0078\u0026\u0021\u005c\u0065\u003a\u0027\u002a\u002a\u0058\u004d\u002b\u005f\u0075\u0030\u0075\u007a\u0059\u0046\u0042\u0074\u002e\u0073\u0028\u003f\u007d\u005a\u0075\u0077\u004b\u006d\u005b\u0023\u005b\u007c\u006d\u0040\u006c\u0047\u0070\u004f\u0075\u0072\u0063\u0029\u0030\u005b\u0026\u007c\u003a\u0026\u0040\u0076\u003c\u003f\u0063\u0057\u004a\u0056\u005e\u0076\u004e\u0022\u0033\u0028\u005a\u006a\u0069\u0040\u0055\u005a\u005c\u002f\u0065\u005b\u0025\u007d\u0024\u0070\u0074\u0059\u0043\u0033\u0065\u0030\u006c\u0052\u0036\u0056\u004e\u0071\u0036\u007b\u002d\u0020\u0076\u0076\u003b\u006b\u004b\u0044\u0060\u0050\u007c\u0072\u0046\u007a\u0045\u0062\u0048\u005f\u002b\u0045\u003b\u004b\u0044\u0077\u0040\u004d\u0058\u0070\u0033\u0066\u003b\u0035\u0026\u0039\u0065\u006d\u0041\u0026\u0043\u0027\u003d\u0034\u0051\u002d\u0031\u006f\u0031\u006c\u004c\u007e\u0069\u0038\u0039\u0066\u0039\u003f\u004f\u0021\u007d\u0031\u0022\u0020\u005c\u007c\u0071\u0039\u0063\u0064\u0030\u005a\u006e\u003c\u003d\u0047\u007c\u007e\u003b\u006b\u0078\u0021\u0043\u004f\u0042\u005a\u0039\u0045\u0062\u004d\u007a\u004a\u0074\u0024\u002d\u0077\u0033\u0077\u0045\u0033\u0032\u0026\u006f\u0039\u0033\u003f\u004b\u006c\u0022\u007a\u003c\u0049\u0058\u0031\u007e\u0044\u004f\u0062\u0034\u005a\u007d\u0065\u005c\u0067\u007b\u007a\u0079\u004b\u007e\u0072\u002d\u0031\u0023\u007e\u007b\u0070\u0022\u002c\u0041\u0023\u0031\u0039\u0026\u0046\u0037\u0048\u005b\u0061\u0020\u003d\u0039\u0065\u003a\u002a\u0033\u0038\u0047\u0069\u0051\u007e\u0064\u0043\u0044\u0076\u0051\u0028\u006f\u007c\u0025\u005e\u005e\u002e\u0049\u006b\u0075\u003f\u003b\u0028\u0025\u002d\u0044\u005b\u0064\u003d\u0059\u0079\u002d\u005d\u0020\u0069\u0067\u0042\u002f\u0078\u0061\u0050\u0079\u0057\u003b\u005b\u007c\u003d\u0050\u0059\u006b\u0053\u003b\u006b\u004a\u002b\u0041\u0049\u0032\u0076\u0076\u0022\u0039\u0026\u002f\u0047\u0044\u0036\u0056\u007b\u007e\u005a\u0027\u0030\u004c\u0077\u007e\u0042\u005d\u003a\u0020\u0034\u002f\u0053\u0036\u003b\u005e\u0076\u0031\u002e\u0027\u005d\u005a\u0066\u004d\u005d\u0077\u004d\u0077\u0021\u0068\u0047\u007d\u0032\u0020\u0073\u0048\u004b\u005a\u0040\u0031\u0038\u0075\u005d\u004f\u0052\u003a\u007b\u0059\u0050\u0034\u007c\u0070\u005a\u0071\u002a\u0028\u0028\u0042\u0074\u007b\u0067\u0023\u0033\u002a\u005f\u0063\u0030\u0043\u0058\u0034\u0065\u0064\u005e\u0040\u0076\u0027\u0023\u0025\u005e\u0063\u0075\u0032\u0044\u0067\u0070\u002d\u002d\u005d\u007b\u0045\u003c\u0067\u002b\u002f\u0040\u002e\u004b\u0039\u0074\u007d\u0064\u004f\u0025\u006c\u002d\u007d\u004f\u0021\u002e\u0071\u004c\u0047\u0074\u006a\u0062\u0057\u0072\u005b\u006e\u003d\u005b\u006b\u004d\u0044\u0051\u0068\u0021\u005d\u0067\u0041\u002c\u0025\u002b\u0050\u0057\u0024\u003f\u005f\u0074\u0038\u0064\u0030\u004e\u005f\u004a\u0050\u003c\u0054\u006a\u0062\u002d\u0072\u004d\u0027\u0045\u0058\u0051\u0051\u005b\u0064\u0039\u0058\u0040\u0051\u0057\u002c\u0075\u003d\u0055\u006f\u0038\u0065\u0043\u0029\u0023\u007e\u0075\u0037\u006d\u0025\u0039\u002f\u0032\u0031\u003d\u0079\u007e\u006d\u0046\u0037\u0063\u0062\u0066\u0076\u0059\u0066\u006e\u0034\u0030\u007a\u0079\u007d\u003c\u0020\u0063\u0058\u0074\u004a\u0055\u0068\u007d\u0024\u0079\u0033\u005c\u005b\u0038\u0065\u0047\u0044\u0049\u006f\u0026\u0064\u002c\u005a\u0056\u0050\u0067\u0021\u0058\u0029\u0062\u0035\u0072\u0031\u0048\u005c\u0078\u0058\u0052\u007e\u0057\u007e\u0021\u0062\u0027\u005f\u0047\u0040\u0029\u0076\u006f\u003d\u002f\u0075\u0031\u0030\u0070\u0028\u0030\u003e\u0067\u0056\u0074\u0041\u0034\u0074\u0038\u005f\u007b\u006b\u0027\u005f\u0047\u0041\u006c\u0070\u0074\u003b\u004b\u0048\u0047\u0055\u007a\u005a\u003d\u0046\u006d\u0062\u0064\u0049\u0048\u0028\u0032\u0060\u002d\u0036\u0063\u0025\u0064\u0028\u005f\u002e\u0025\u004d\u0029\u003e\u0024\u0061\u0027\u0070\u004f\u0022\u007a\u0072\u0051\u0060\u004c\u0037\u0034\u0032\u0057\u005e\u0043\u002b\u0039\u0042\u0038\u005a\u004f\u0027\u0044\u0068\u0061\u0026\u005e\u003f\u0035\u0021\u004c\u0078\u002b\u004b\u0042\u006a\u0027\u0041\u0029\u0061\u0075\u0034\u0039\u0020\u0077\u0020\u003d\u0066\u0036\u0064\u002d\u006a\u0032\u0073\u0034\u005c\u0049\u0038\u0032\u005a\u002a\u0055\u004c\u0078\u0071\u0027\u0037\u004d\u0058\u004e\u004e\u0020\u0071\u007c\u0047\u0057\u0060\u004a\u004c\u0079\u003c\u003c\u002e\u0074\u006b\u0061\u0043\u005f\u003e\u0032\u0069\u0069\u0073\u0068\u0059\u002c\u0077\u0028\u0033\u002f\u0072\u0026\u006d\u002a\u004f\u0077\u0060\u0050\u0022\u0070\u003c\u0026\u0060\u0047\u005a\u0047\u0068\u005e\u003e\u0043\u0038\u0070\u007d\u006c\u0075\u0031\u005f\u0072\u006e\u0030\u0074\u0074\u0077\u0054\u0051\u0027\u006d\u006f\u0079\u0056\u0069\u002f\u0029\u0057\u0069\u005a\u0025\u006e\u0042\u0078\u0042\u0061\u0076\u0052\u005d\u0064\u0045\u0029\u0024\u003a\u003b\u002a\u0063\u0060\u0037\u0071\u0061\u007d\u0051\u0055\u0053\u0027\u007e\u003f\u003b\u002c\u0039\u0039\u002e\u0044\u007d\u0053\u0041\u0070\u0028\u002d\u0065\u0055\u0052\u003a\u004b\u0043\u005c\u006b\u0026\u0021\u0034\u0073\u006d\u0060\u0075\u0068\u0026\u002d\u006e\u005f\u004c\u0036\u0060\u0048\u003e\u002c\u0042\u005b\u007d\u005b\u0040\u0069\u0052\u0059\u0055\u0071\u006c\u0036\u0022\u0073\u002e\u0027\u0076\u0035\u007d\u0071\u002a\u007a\u0027\u005f\u0044\u007b\u004f\u007d\u002c\u0022\u0077\u0044\u0047\u003b\u0033\u0073\u0063\u0032\u0063\u004c\u0038\u0048\u0052\u0031\u0024\u004b\u0023\u0070\u0056\u0022\u003d\u0075\u0045\u0066\u0064\u0044\u005f\u0058\u006e\u0052\u0069\u0048\u0042\u0070\u0055\u003e\u0032\u003e\u0028\u002e\u0050\u005a\u0073\u0069\u002d\u0056\u0076\u0061\u003e\u002a\u0037\u007c\u0029\u0047\u0024\u005c\u0066\u0023\u007d\u006c\u0076\u0049\u007e\u0031\u003c\u0079\u006c\u002a\u005d\u0049\u0032\u0077\u0039\u0026\u0042\u005f\u0025\u005b\u0029\u0034\u007a\u0036\u0035\u0067\u005a\u0057\u003c\u004b\u004e\u006f\u006e\u0050\u005b\u0058\u0043\u0072\u0074\u005a\u0036\u0047\u005c\u003f\u0050\u004d\u0046\u0055\u0024\u0071\u0077\u0029\u0030\u006b\u0058\u0054\u0042\u0060\u005a\u0044\u005d\u0031\u002c\u0022\u0066\u0073\u003a\u0069\u0026\u0061\u0048\u003b\u0070\u0052\u003c\u006b\u003d\u0032\u0035\u0077\u004d\u0020\u0060\u0029\u003d\u0029\u0072\u005a\u0066\u004b\u004c\u0037\u006d\u0059\u0028\u0026\u0065\u0070\u003e\u0029\u0055\u0046\u0072\u0032\u0025\u006d\u004d\u003d\u007a\u0079\u0054\u0074\u0039\u0061\u0076\u005b\u007c\u0025\u0028\u0049\u0059\u0062\u0024\u0050\u0054\u0062\u0033\u0047\u0064\u0051\u0079\u0049\u0064\u0036\u0049\u007c\u007b\u0058\u0021\u0039\u0031\u004c\u002e\u0026\u0050\u002b\u003e\u0037\u0062\u002e\u0024\u0038\u006c\u005a\u007a\u0066\u005e\u0054\u0057\u0066\u0047\u005e\u0020\u005d\u0029\u003a\u0025\u007d\u004c\u003e\u0070\u0071\u0037\u0031\u0024\u003a\u0024\u0051\u0027\u0070\u0051\u0028\u0052\u0079\u005c\u0031\u0057\u0036\u0060\u0066\u0041\u0022\u003e\u002d\u0054\u007e\u005d\u0020\u004d\u0060\u0076\u0037\u0042\u0059\u0059\u006e\u004c\u0024\u004f\u0028\u0041\u0027\u0059\u0034\u0056\u0049\u0030\u007c\u0071\u004c\u0077\u0062\u004c\u0040\u004f\u0049\u007b\u0048\u0072\u007e\u002b\u0060\u0025\u005f\u005a\u004f\u0040\u0050\u002e\u005b\u0023\u005e\u0023\u002d\u0072\u0020\u0064\u0043\u0065\u0061\u004b\u0030\u0069\u0078\u006a\u0037\u0071\u002a\u0078\u007a\u0021\u003e\u0023\u005d\u0029\u004e\u0029\u0064\u0043\u002b\u002f\u006d\u0068\u0072\u004d\u004c\u0049\u0066\u007c\u0064\u0049\u005f\u005e\u002c\u0021\u0048\u004f\u0021\u0042\u006e\u0053\u0060\u007b\u0067\u007e\u0036\u0029\u0058\u005e\u0037\u0029\u0039\u0040\u0031\u0040\u007b\u006e\u005a\u0049\u0073\u0074\u004d\u0025\u0030\u004a\u0048\u0045\u007e\u0063\u0025\u0064\u005c\u0070\u004a\u004f\u0030\u0033\u007a\u0022\u007a\u003d\u0032\u006f\u004c\u002f\u0025\u0075\u0075\u0023\u007c\u0052\u006a\u0029\u0028\u006a\u0075\u006c\u0060\u004c\u007c\u005b\u002e\u0064\u004f\u0051\u0050\u0061\u0046\u0052\u0028\u0069\u002e\u0066\u0028\u0023\u0030\u004e\u003e\u0065\u003c\u003f\u004a\u0027\u004a\u0062\u002c\u0023\u0037\u005f\u0030\u0033\u0023\u005c\u0060\u004a\u0024\u0024\u0044\u003c\u0053\u005d\u0073\u004c\u003e\u0044\u0029\u0050\u0048\u007d\u0028\u007c\u006d\u0059\u0024\u0077\u0060\u002f\u0076\u0073\u0048\u006f\u0021\u002f\u003d\u0057\u0058\u0064\u004e\u0025\u0064\u002b\u0023\u0049\u002c\u0027\u007b\u0030\u0044\u0069\u004e\u006b\u0059\u0034\u0077\u006f\u0058\u0022\u0060\u002a\u0032\u0039\u0025\u0070\u002e\u0039\u0060\u0049\u0025\u0054\u007e\u0050\u0051\u0076\u002e\u0043\u0075\u002f\u0077\u0036\u0021\u004c\u003f\u0069\u0048\u005a\u0051\u0060\u007e\u004c\u0078\u0077\u0066\u002d\u0038\u0034\u0047\u003f\u0044\u0035\u0070\u004a\u002c\u002f\u0058\u0054\u0028\u0041\u0021\u005b\u006e\u003e\u007c\u006e\u007b\u0050\u0062\u0051\u0067\u0037\u003e\u0031\u0039\u0061\u0024\u0065\u003e\u0065\u007a\u0042\u006a\u003a\u004e\u005e\u0047\u007c\u0066\u0044\u0040\u0068\u0034\u003b\u0040\u0067\u0029\u0024\u0027\u003d\u005a\u0053\u003e\u0061\u0042\u003a\u0055\u007c\u0041\u006c\u0066\u0054\u007e\u0070\u0051\u0061\u0035\u005f\u0035\u0066\u0069\u0068\u0028\u0034\u0029\u007a\u0052\u0033\u0078\u002b\u0060\u006c\u0024\u0027\u0026\u005c\u0068\u005d\u0069\u005a\u0062\u0062\u0071\u0020\u0034\u006e\u007e\u005f\u003c\u0050\u002d\u005b\u007c\u0026\u0045\u0066\u002a\u0025\u0061\u007b\u0054\u0062\u0040\u0030\u006f\u003a\u0064\u002f\u0058\u002e\u0066\u005e\u0029\u0020\u0054\u0046\u0024\u004c\u0023\u0046\u0063\u004a\u0029\u0067\u0057\u0029\u0044\u006a\u0064\u0050\u0033\u0020\u0048\u0050\u0044\u0076\u0040\u0044\u005c\u0021\u0034\u0033\u007d\u0071\u0071\u0031\u0059\u0057\u0039\u004d\u003c\u0067\u0048\u0056\u002d\u004b\u002a\u0061\u0056\u002b\u0068\u0032\u004c\u005a\u0077\u002c\u005c\u0033\u004e\u006a\u0051\u0067\u0035\u006f\u0051\u006f\u0064\u005f\u006d\u006c\u0071\u0060\u005b\u004b\u004f\u0076\u0055\u0038\u0043\u007e\u003a\u0044\u0070\u0078\u005b\u0045\u0030\u0035\u0028\u0024\u0057\u005f\u005c\u0027\u0063\u005a\u0032\u002e\u0077\u0031\u0032\u0073\u0029\u0033\u0039\u002c\u002b\u0051\u0023\u002d\u004c\u005d\u0051\u003e\u0020\u0078\u0043\u0036\u0067\u004c\u0040\u0022\u002c\u0042\u0070\u0051\u0043\u002e\u005e\u0067\u007e\u003f\u0067\u007d\u004e\u0058\u007d\u005d\u0041\u006c\u0043\u0060\u0050\u0042\u0031\u003b\u0028\u0038\u005e\u0047\u004d\u004e\u0040\u0056\u003b\u0032\u006b\u002b\u0073\u006c\u004d\u0066\u0026\u005a\u007a\u004e\u0047\u0075\u0022\u0042\u0029\u0036\u0057\u0030\u0027\u005d\u0023\u0073\u0048\u0051\u0037\u0050\u005b\u005d\u004f\u0070\u0071\u007d\u0077\u006a\u002b\u0047\u006f\u0052\u004a\u005a\u006a\u005a\u0058\u0071\u004a\u0042\u0042\u005a\u0041\u0021\u006e\u002d\u0034\u0078\u0078\u006d\u0038\u003c\u0058\u002b\u003b\u0022\u0077\u0069\u005b\u0074\u006a\u0022\u007b\u004b\u004e\u0037\u0034\u007e\u003e\u0037\u0055\u0029\u0064\u0057\u0068\u0038\u005f\u005c\u004d\u0076\u0047\u0059\u002b\u005b\u0031\u0030\u0027\u0053\u0048\u0042\u0068\u0071\u0066\u0074\u006e\u005c\u0047\u0066\u007a\u004e\u0035\u0032\u003f\u003b\u0067\u0032\u0029\u007e\u0025\u0024\u0042\u002b\u004f\u005b\u006f\u0028\u006f\u0069\u0052\u002e\u0059\u002f\u0066\u005f\u0063\u0067\u0023\u0021\u004f\u0023\u0048\u0052\u007e\u0049\u003e\u004b\u004b\u005d\u0046\u007d\u0063\u0067\u0065\u003e\u003d\u0074\u003e\u004b\u004c\u003c\u0051\u0032\u0020\u006b\u0024\u007d\u002f\u004d\u004d\u0071\u0028\u007e\u0056\u0076\u007a\u0036\u0030\u0070\u006d\u005c\u003b\u004b\u0036\u003e\u0066\u0065\u0034\u0055\u0076\u0067\u0023\u0074\u0035\u004c\u003b\u0060\u0057\u0064\u004c\u0051\u0034\u0066\u0021\u0020\u004c\u0056\u0024\u003d\u0033\u0076\u0032\u006e\u0045\u0043\u0066\u0076\u0056\u004d\u0060\u0037\u0079\u002a\u006d\u006b\u0038\u006d\u0047\u0069\u0031\u0065\u0047\u004c\u004c\u0023\u005e\u0026\u0072\u0040\u003f\u006f\u0025\u004d\u005d\u002f\u0068\u002f\u007d\u007c\u0054\u0042\u006e\u0040\u0062\u0064\u007c\u0032\u006c\u005a\u0036\u005a\u003e\u0044\u0042\u0060\u005e\u0078\u0043\u005d\u005c\u0077\u007b\u0049\u0078\u0074\u004e\u002e\u005c\u004e\u0076\u0025\u003d\u0059\u007b\u0038\u006d\u007e\u0077\u002d\u007b\u0033\u0038\u002f\u007b\u0035\u005b\u005c\u0040\u0050\u004e\u006e\u0074\u002a\u0067\u007a\u0042\u003d\u0040\u0071\u0037\u0037\u0075\u0064\u0074\u003a\u0046\u006a\u0059\u005f\u0041\u003e\u005b\u0036\u007d\u003e\u0037\u003d\u0038\u002f\u003c\u0039\u0024\u0026\u005c\u0048\u0061\u004a\u003c\u003c\u0025\u0062\u0063\u0067\u006d\u0021\u0060\u0067\u0056\u0079\u002e\u0038\u003d\u003e\u0078\u007b\u0046\u0072\u0072\u005c\u006e\u0044\u005f\u0036\u0034\u0048\u0032\u0069\u0053\u003c\u0051\u0023\u006a\u003c\u0061\u0040\u005f\u003b\u0031\u0070\u0038\u0033\u0044\u0052\u0046\u0057\u0069\u003e\u0043\u0067\u005a\u0034\u0033\u0071\u0026\u0077\u0056\u0021\u0025\u003d\u0032\u007e\u006f\u006c\u0057\u0045\u0027\u0073\u007d\u004b\u0077\u0030\u006d\u0056\u005a\u0027\u007c\u005c\u0036\u0066\u004e\u002b\u003a\u0065\u0036\u0074\u0051\u0033\u0065\u0040\u0024\u005c\u0077\u0070\u0049\u0027\u003a\u0054\u0034\u004b\u007b\u0062\u0071\u007d\u0020\u002b\u0034\u0072\u0077\u004c\u003c\u0026\u0053\u002f\u003e\u007a\u0031\u003c\u004e\u007e\u007e\u0048\u007e\u004c\u0039\u0030\u0055\u0025\u0023\u007c\u0039\u005c\u004d\u005a\u006d\u0059\u0059\u004b\u005e\u002c\u007b\u005b\u0078\u005f\u0050\u0044\u0043\u0065\u0077\u003c\u0051\u0073\u005f\u0053\u004c\u0026\u005e\u0076\u0063\u002f\u0039\u004b\u0038\u0043\u0061\u005a\u0021\u0067\u0043\u002e\u005c\u0058\u0020\u0064\u0071\u004c\u0063\u007d\u0063\u0050\u0047\u005e\u0046\u0056\u004c\u0067\u002d\u003d\u006e\u003d\u0026\u005c\u0069\u0039\u002e\u003b\u0053\u0026\u0072\u002e\u0023\u0069\u0031\u0061\u0074\u003e\u0031\u0079\u002d\u007d\u002d\u0041\u0075\u0056\u0072\u0071\u004b\u0070\u002c\u0046\u004c\u0035\u0044\u0067\u007e\u006b\u005a\u005a\u004f\u0054\u002d\u006f\u004f\u0034\u004c\u0045\u003a\u0036\u0040\u002f\u0058\u0027\u0076\u0076\u003f\u003a\u004a\u003e\u0042\u006d\u006f\u002d\u0041\u0024\u003a\u0056\u0056\u0052\u006a\u0067\u004b\u0069\u0060\u0031\u0030\u0027\u005c\u002c\u003b\u0041\u0067\u0023\u005f\u004e\u006c\u006f\u005f\u0021\u005b\u0055\u002d\u004d\u0079\u0022\u007b\u0021\u0051\u0063\u0033\u0070\u0076\u0078\u0051\u0034\u0058\u005d\u0064\u003b\u007a\u003d\u004f\u004a\u0035\u0047\u0079\u004f\u003c\u0064\u0070\u0056\u0046\u0031\u0062\u0028\u0073\u006d\u003a\u0059\u0076\u0048\u0057\u007b\u002b\u0078\u0065\u0069\u005b\u0074\u002f\u0061\u005b\u0020\u0076\u0062\u0050\u005c\u0034\u006b\u0067\u0075\u004b\u006e\u0079\u0054\u006e\u0032\u0024\u005c\u0059\u0055\u0026\u0050\u0072\u0038\u002e\u0056\u0039\u005f\u0055\u0023\u0051\u004f\u0068\u003f\u006b\u0048\u0039\u0047\u006e\u005c\u006a\u0031\u0047\u0059\u0040\u0057\u0045\u004b\u004d\u003c\u002c\u0020\u0050\u0053\u005d\u0030\u005a\u0049\u0079\u0051\u0049\u0070\u0045\u0068\u0031\u005c\u0050\u0044\u0042\u0065\u006d\u0050\u0039\u0064\u005d\u0031\u0061\u0024\u0071\u005d\u0056\u0064\u003d\u0044\u005f\u0078\u0036\u002d\u0053\u0043\u0022\u0020\u005a\u004e\u0064\u0038\u0029\u005a\u0047\u0053\u003c\u0040\u0023\u0078\u007a\u007d\u0031\u0079\u0028\u0021\u0024\u0060\u004f\u0054\u007b\u007d\u002a\u0043\u0031\u006e\u004c\u002a\u002b\u0040\u0022\u002f\u0060\u0070\u0033\u0061\u0059\u0076\u0072\u0027\u0029\u002c\u0042\u0068\u0050\u003a\u003d\u002e\u0074\u007b\u0059\u0061\u0071\u005e\u0071\u0044\u005b\u0036\u0064\u006a\u004a\u0043\u0027\u0067\u0031\u003f\u0073\u0025\u0050\u0023\u0071\u0059\u005a\u0051\u0023\u0020\u0025\u0069\u0026\u006b\u006c\u0055\u0062\u005f\u006e\u0073\u0052\u0031\u0021\u0031\u005c\u0042\u0050\u0047\u002f\u0060\u0029\u0065\u0073\u007d\u0076\u0031\u0020\u004f\u0064\u006c\u0077\u0076\u0076\u0023\u0056\u0069\u0048\u0076\u0024\u0074\u002e\u0067\u005b\u0062\u004c\u0077\u0074\u0026\u0022\u005b\u007c\u0059\u0072\u0077\u0043\u002a\u0022\u005c\u0059\u004a\u0046\u002d\u002d\u004c\u0027\u0032\u0059\u0065\u002a\u003c\u0022\u0067\u0054\u0036\u0038\u004e\u003f\u0030\u0060\u0023\u0024\u004d\u006b\u0059\u0073\u0040\u002f\u0075\u0072\u0033\u0029\u0027\u0044\u0028\u0066\u0069\u0020\u002b\u0049\u0059\u0069\u0041\u0071\u002a\u005e\u0029\u0050\u0075\u0055\u003a\u0022\u0079\u0023\u006d\u0020\u007a\u002e\u0047\u0021\u0027\u0062\u0079\u0040\u0039\u004c\u005c\u003f\u0054\u005e\u0071\u0026\u004c\u0041\u0042\u003d\u0058\u0058\u005c\u003b\u0049\u005a\u002c\u0053\u005b\u006d\u0055\u007a\u003e\u0055\u0045\u005c\u006f\u004e\u003e\u0037\u0023\u0028\u007a\u0073\u003a\u0072\u0037\u007e\u0038\u0023\u0051\u005b\u0047\u005d\u0079\u0025\u0075\u005d\u0052\u003f\u0025\u0075\u0066\u0036\u0067\u0059\u002d\u007e\u0049\u0034\u0040\u005b\u002f\u003b\u0054\u0043\u0057\u0058\u0053\u006e\u006e\u004a\u0056\u002c\u006c\u0037\u0028\u0037\u0022\u0024\u0039\u0057\u004c\u0049\u007d\u006d\u004c\u005c\u003c\u0042\u002a\u0043\u0073\u0030\u0060\u0024\u007b\u0048\u002a\u0042\u002b\u006c\u002e\u006d\u0022\u0063\u0048\u0024\u0065\u0054\u0024\u0065\u006f\u0025\u003f\u0034\u007a\u006f\u0069\u0065\u0066\u0065\u0044\u0050\u0076\u005c\u002d\u0041\u0071\u0024\u0036\u006d\u004c\u0038\u0079\u0039\u002c\u007e\u0056\u0062\u002d\u0056\u0056\u0032\u0042\u0031\u006c\u0034\u0030\u0072\u006e\u0077\u003e\u0058\u006e\u0079\u005d\u0026\u002e\u0030\u005f\u0029\u007e\u0029\u0079\u005a\u006f\u0053\u0040\u0043\u0023\u0045\u0020\u003f\u007b\u0026\u0042\u0027\u0031\u0041\u0074\u0027\u002b\u0046\u0069\u0055\u0024\u0049\u006d\u0055\u004a\u0064\u003a\u0049\u006b\u006e\u0039\u0058\u006c\u006f\u0041\u0040\u0054\u007d\u0021\u0075\u007c\u0031\u005e\u0079\u0029\u0030\u002a\u0036\u0060\u007b\u0067\u004c\u003a\u0057\u0034\u0041\u003f\u004e\u006f\u002f\u0027\u002e\u0029\u0055\u007b\u005b\u0072\u0032\u0075\u007e\u0067\u005b\u006b\u0020\u0064\u003f\u0035\u0079\u0039\u007e\u0020\u006b\u0050\u004f\u0032\u0048\u0047\u0031\u0051\u0077\u0064\u0034\u003f\u0056\u0061\u004e\u003a\u003a\u0066\u0057\u006c\u005d\u0052\u002a\u0060\u005d\u004e\u0039\u0044\u002a\u0038\u0027\u0054\u004b\u0042\u0061\u0070\u002f\u002e\u0079\u0068\u0051\u003e\u0067\u0076\u007d\u006b\u0042\u0069\u003d\u0076\u005c\u0057\u0035\u0057\u0054\u005b\u0030\u004f\u0050\u005f\u006e\u006d\u006a\u0058\u0045\u002f\u005d\u002b\u005e\u0020\u0077\u003c\u0048\u006b\u0049\u005d\u0024\u005f\u002e\u0060\u0027\u0073\u0050\u0022\u0069\u0033\u007b\u006b\u005a\u004e\u0033\u0058\u004b\u004f\u0053\u0029\u0061\u003c\u0070\u0078\u0043\u0054\u004d\u0072\u0074\u005e\u005e\u002c\u002a\u0026\u0026\u004f\u0064\u0059\u0059\u0040\u0036\u007b\u0036\u004e\u0022\u0059\u007d\u0072\u004d\u0039\u0077\u0044\u003a\u0059\u0032\u0038\u0077\u004c\u0023\u0042\u004c\u0060\u006a\u0055\u0055\u005e\u0068\u0043\u006a\u004c\u005a\u0065\u006b\u0070\u0068\u006c\u0022\u0048\u0070\u0037\u005a\u005d\u0039\u0050\u0032\u0064\u0076\u0036\u004c\u0079\u005f\u006b\u0055\u0046\u004b\u0045\u0076\u006d\u0039\u0070\u0048\u0055\u004d\u005d\u002d\u0020\u002e\u0039\u003d\u0062\u003c\u005a\u003b\u0040\u0029\u0048\u0043\u0058\u0063\u006d\u0057\u0046\u0034\u0039\u0060\u006c\u004b\u0075\u003f\u0039\u0053\u006a\u003b\u0023\u0068\u0027\u003d\u0078\u006e\u002a\u0067\u0057\u0033\u005a\u0032\u0034\u0064\u0046\u0030\u006d\u007d\u0062\u0035\u0038\u0074\u0056\u0037\u002a\u0051\u0059\u0022\u0069\u004c\u0028\u0074\u004e\u0036\u007a\u0053\u0038\u003f\u006f\u0078\u005b\u0062\u0025\u006a\u004d\u0030\u0068\u002a\u0065\u0073\u003b\u0020\u0051\u007d\u002c\u005b\u004e\u0051\u003e\u0078\u0040\u0049\u0035\u0064\u0045\u002e\u0069\u0034\u0025\u0057\u0054\u0048\u0062\u0020\u0032\u0055\u003d\u0063\u005a\u0020\u002a\u0068\u002f\u0070\u0072\u0045\u002b\u0020\u0071\u0021\u0049\u0053\u0033\u0076\u002d\u0026\u007e\u005e\u0050\u005b\u002c\u0033\u0033\u0077\u0079\u007b\u0073\u0079\u007c\u006c\u0034\u006a\u0035\u0077\u007a\u0054\u0068\u0063\u007b\u004a\u0061\u0026\u0029\u0074\u0021\u004b\u0057\u006d\u003e\u004d\u0038\u0030\u003a\u003a\u0057\u0027\u003b\u006a\u007a\u006e\u004f\u007e\u0067\u002c\u0061\u0047\u0025\u005b\u0077\u0031\u0030\u0047\u0040\u005a\u0068\u004c\u0070\u0070\u002f\u0047\u004e\u007a\u0068\u0068\u0073\u003c\u0044\u0023\u0032\u004f\u006d\u006f\u003e\u0065\u002b\u002b\u007d\u0044\u007d\u002b\u002d\u0041\u0071\u0023\u0036\u005c\u0025\u0061\u0028\u0048\u0056\u0025\u004a\u0026\u0040\u0059\u0076\u003e\u007a\u004e\u0027\u0064\u002d\u0036\u006a\u0067\u0058\u0061\u0066\u0054\u007a\u0048\u006f\u0023\u005b\u0064\u0027\u0050\u005b\u007c\u0066\u003c\u0041\u0038\u003c\u007e\u002f\u005a\u0071\u0039\u0052\u0038\u0050\u0075\u0047\u0074\u0076\u0036\u0028\u003d\u0048\u0029\u0054\u0051\u0052\u0057\u006c\u0076\u0044\u0047\u0038\u0073\u0059\u006d\u002d\u0055\u0030\u0020\u0078\u003c\u0044\u0030\u0054\u007a\u006f\u0021\u0060\u0039\u0033\u0065\u006a\u006d\u002f\u004a\u0034\u002c\u007e\u0038\u0053\u0052\u0041\u0071\u0044\u007e\u004e\u003f\u003a\u0030\u0068\u006b\u007a\u006f\u0070\u003b\u007a\u0037\u002b\u003d\u003c\u006d\u0079\u002e\u0078\u005a\u0030\u004e\u005f\u0079\u007e\u007c\u005b\u0050\u0077\u006f\u0078\u0059\u0061\u0041\u0069\u007b\u0050\u0028\u0061\u0026\u0046\u0079\u0034\u0048\u0028\u0076\u0045\u0065\u0070\u002a\u0034\u0039\u002b\u0065\u0023\u0075\u0028\u006f\u003d\u0028\u0073\u0075\u006c\u0075\u005b\u0054\u0036\u002c\u0064\u002c\u0059\u0039\u007c\u0045\u005a\u0067\u005d\u004e\u0020\u002a\u0042\u006d\u0052\u0063\u0062\u0048\u005a\u002a\u0068\u0079\u0062\u004f\u006c\u0064\u002a\u002a\u006b\u0027\u0051\u0030\u006d\u0076\u0021\u0034\u0072\u0057\u0062\u0024\u0055\u0025\u0071\u005f\u0077\u0068\u007d\u007e\u0041\u003a\u0032\u0061\u002f\u004e\u0058\u0031\u0025\u0078\u0079\u0055\u0046\u0029\u006d\u0030\u0020\u005e\u0023\u003a\u0070\u0032\u0049\u0033\u0028\u0063\u0077\u0039\u007b\u0065\u0021\u0020\u005e\u007c\u0046\u003e\u0023\u0035\u0030\u0052\u0039\u0053\u007e\u0038\u004a\u0040\u0024\u0051\u0043\u006b\u0029\u002d\u0067\u0071\u0056\u003c\u0041\u0058\u003c\u002a\u0077\u006b\u0033\u006b\u0052\u003a\u0052\u0027\u0024\u004c\u003d\u003d\u003b\u0059\u0040\u003f\u0072\u002a\u0074\u004d\u0037\u0062\u006b\u0036\u004f\u0041\u0031\u0037\u006e\u0048\u0027\u0025\u0033\u0078\u0047\u0052\u003b\u004a\u0045\u0075\u006b\u007d\u004f\u0036\u004a\u0061\u0029\u0050\u002d\u005b\u002f\u0064\u002d\u0062\u006b\u0051\u005b\u006f\u0051\u007d\u005e\u005a\u004b\u0033\u003e\u003f\u002e\u0069\u0025\u0053\u0047\u0030\u007c\u002b\u0025\u0026\u004d\u0049\u004f\u005f\u002e\u0049\u0058\u0073\u0049\u0029\u0030\u0040\u0023\u0061\u002c\u0046\u006a\u0076\u0025\u0026\u0071\u0025\u0053\u0075\u0029\u005c\u003a\u003f\u0078\u0043\u0062\u0021\u0062\u0021\u0028\u0077\u0047\u0053\u0076\u0055\u003e\u0073\u0069\u0048\u0048\u0046\u003d\u006d\u0060\u005d\u0054\u0055\u0047\u003e\u005b\u004f\u0070\u0053\u0037\u005b\u0021\u0036\u0053\u0028\u0034\u005e\u0028\u006f\u0077\u002c\u0056\u0039\u0049\u004f\u002f\u0051\u002d\u0040\u0053\u0051\u0027\u005c\u007a\u005d\u002c\u003b\u0070\u0074\u0049\u004c\u0044\u0074\u005a\u007a\u002b\u0045\u0065\u0076\u0026\u0041\u0054\u0029\u002f\u0034\u0073\u002d\u003d\u0043\u0046\u007e\u006a\u0052\u0060\u006c\u0068\u0055\u002f\u0033\u0026\u0077\u002c\u0062\u0023\u006d\u0036\u003a\u0055\u005f\u0057\u002d\u004a\u007b\u0041\u004e\u0050\u0072\u0037\u0041\u006a\u0070\u0040\u0026\u002b\u0070\u006d\u0076\u0041\u004b\u0043\u007a\u0064\u003b\u0077\u003b\u0063\u0051\u007d\u0041\u0046\u006e\u002e\u0052\u0078\u0045\u0055\u003f\u005b\u0076\u0047\u0042\u0041\u005f\u004c\u0068\u0065\u0030\u0029\u007d\u0071\u006b\u004d\u006d\u0055\u002f\u0021\u002f\u003f\u0051\u0037\u0044\u0058\u006f\u0043\u007d\u006e\u0066\u0074\u0073\u003a\u002c\u0055\u0068\u0062\u006b\u005f\u0078\u0026\u0062\u002f\u0061\u0040\u0064\u0079\u0028\u0046\u0041\u005c\u0056\u0044\u0068\u005f\u0032\u0052\u002e\u002b\u0071\u0071\u0032\u0023\u0066\u0077\u005a\u007b\u0048\u0022\u002c\u005a\u002e\u006d\u0038\u0066\u0068\u006f\u0029\u0033\u002c\u0040\u0057\u0059\u0030\u0051\u005a\u0034\u003e\u003c\u004b\u002e\u0023\u006a\u004d\u005b\u005a\u003f\u005f\u006b\u0075\u0036\u0076\u0064\u0030\u0076\u004a\u007a\u0030\u0038\u004c\u002f\u0036\u007d\u0045\u0078\u004d\u003b\u0078\u004c\u0041\u0075\u0052\u0034\u0077\u0030\u0064\u005d\u0044\u004b\u0068\u0050\u0060\u0038\u005c\u0049\u006f\u006e\u005c\u006c\u005c\u005c\u0079\u0063\u0048\u0073\u0069\u0026\u0024\u003b\u007a\u006b\u004f\u0033\u002b\u0032\u0066\u0049\u0068\u0066\u0077\u0062\u005c\u0025\u003e\u0061\u006c\u0026\u0065\u003e\u003d\u002f\u003d\u0055\u002e\u0027\u0063\u0046\u0038\u0063\u0041\u0037\u002e\u0028\u0066\u0062\u0053\u003b\u0024\u0071\u004c\u0040\u005e\u0060\u003f\u006c\u0045\u006d\u0076\u0040\u005b\u006c\u0047\u0046\u0067\u0074\u0034\u0034\u0058\u0050\u004e\u005f\u005b\u0071\u0050\u002c\u0046\u0039\u007d\u0021\u005b\u0077\u0064\u0042\u0040\u003c\u0066\u0056\u0048\u0048\u006d\u0036\u0070\u0021\u005d\u0051\u0040\u004f\u0031\u005d\u0043\u0034\u007c\u0023\u0070\u0050\u0030\u006a\u002a\u0061\u0049\u0062\u0061\u007d\u003b\u0041\u0028\u006c\u0026\u0075\u0046\u003e\u005d\u0077\u002c\u0069\u0055\u0060\u004d\u0051\u002b\u006a\u007a\u0065\u0067\u004f\u002c\u0058\u0073\u0049\u0054\u0036\u0069\u007c\u0039\u0050\u0077\u003d\u006d\u0055\u003f\u0032\u0065\u002f\u0078\u007e\u0057\u007a\u0053\u0030\u0030\u0060\u0068\u0035\u0068\u0075\u0077\u0050\u007d\u003c\u004f\u0076\u003b\u002a\u007e\u0075\u002e\u006c\u0038\u0050\u004a\u0025\u0076\u004c\u0043\u002d\u0035\u0069\u002b\u004a\u0020\u0047\u006d\u0033\u004f\u0027\u0047\u0073\u0054\u0020\u005f\u0066\u0079\u0065\u0053\u005b\u007b\u0055\u0050\u0044\u0038\u0045\u0021\u007b\u0037\u003b\u0066\u005f\u0033\u0049\u0051\u0027\u004e\u0077\u0054\u0061\u0033\u003b\u005e\u0035\u0059\u0048\u0044\u0067\u0063\u0033\u007b\u0036\u0050\u0077\u005d\u0025\u005d\u0066\u0044\u005f\u0046\u0040\u003d\u0023\u0076\u0044\u0035\u0079\u0044\u003f\u0074\u0052\u0078\u0042\u0071\u0056\u0059\u0066\u0032\u0033\u0030\u004f\u0050\u0062\u0067\u0027\u0048\u0051\u0030\u006e\u007b\u0065\u0021\u004c\u0039\u005b\u0050\u006b\u0060\u0079\u0025\u0033\u0066\u007e\u0033\u007b\u0050\u006b\u004d\u004c\u0052\u0035\u0020\u0048\u006f\u0057\u0072\u0057\u0037\u0031\u005f\u0031\u005b\u006c\u0028\u0023\u002c\u0036\u007c\u0076\u0042\u0053\u004b\u0061\u0021\u006d\u002c\u0041\u003f\u007d\u006e\u0052\u0079\u003c\u0036\u007e\u007e\u0039\u0059\u004c\u0068\u0079\u0020\u0052\u0026\u0052\u002f\u007a\u0057\u0061\u0065\u003b\u0077\u0068\u0045\u0067\u0032\u0056\u004a\u0023\u0050\u005f\u0025\u0034\u0065\u0068\u0067\u0076\u0025\u0074\u0047\u006d\u006f\u0068\u0030\u002f\u0043\u002a\u003f\u0061\u0036\u0058\u0056\u006d\u004f\u007e\u0037\u0040\u0079\u0050\u0033\u0070\u0037\u002b\u0031\u0056\u0064\u0072\u0068\u0048\u004b\u0027\u004e\u0062\u0046\u0070\u0065\u007a\u0034\u005e\u006b\u0065\u007b\u0028\u0070\u0061\u0072\u007a\u005c\u0065\u007b\u004f\u003a\u007a\u003a\u0048\u003a\u003a\u0023\u0044\u0042\u007a\u007a\u002b\u0063\u0073\u004c\u0076\u004c\u002b\u0071\u0069\u0023\u002f\u0066\u0033\u0067\u0040\u003d\u005e\u0028\u0069\u006b\u0035\u0069\u005c\u0066\u002e\u0024\u006c\u004e\u0027\u002c\u0070\u0048\u003d\u0030\u0030\u0067\u0048\u0051\u0055\u003f\u0042\u006c\u005f\u0035\u0053\u005e\u0037\u0020\u0025\u0038\u0075\u005e\u005d\u0064\u0022\u002e\u0026\u0059\u0069\u006d\u0044\u0029\u0031\u0057\u0049\u0033\u005a\u007c\u004b\u0025\u004f\u0047\u002b\u003d\u0067\u0030\u0025\u004e\u0043\u007d\u0045\u005f\u0045\u0035\u0047\u0055\u007a\u0044\u003a\u0062\u002b\u0070\u0069\u0059\u002e\u0046\u0028\u005c\u007c\u0030\u0074\u004a\u004b\u0029\u0078\u004a\u003b\u002a\u0061\u004c\u0071\u006f\u007e\u0058\u003d\u0041\u002d\u0059\u0058\u004b\u007a\u0022\u0065\u0023\u0063\u0044\u0031\u0038\u0072\u003f\u007a\u0057\u002f\u006f\u0030\u002b\u0054\u006a\u0075\u0051\u0058\u0029\u0035\u007c\u004d\u005e\u0047\u003b\u0060\u005a\u004f\u0056\u0033\u007a\u0030\u0038\u0033\u002e\u0034\u002f\u003e\u0029\u0048\u0052\u002c\u0077\u003a\u0039\u006c\u0035\u0073\u0034\u0061\u0068\u0028\u006c\u0076\u0032\u005b\u0041\u0044\u0068\u003f\u004e\u006f\u0072\u003a\u005b\u007c\u0051\u005c\u0050\u0026\u0078\u004b\u0021\u007b\u003a\u005f\u006b\u0071\u0032\u0052\u0028\u006b\u003a\u0061\u007e\u0075\u0024\u0066\u0064\u0035\u0067\u003d\u002f\u0048\u0063\u0032\u0033\u0036\u0052\u006d\u002f\u002b\u007a\u007d\u0077\u002b\u0043\u0027\u0078\u0032\u0043\u007b\u0061\u0036\u003d\u0045\u0039\u004f\u0043\u005c\u0027\u004d\u0073\u0048\u0077\u005d\u0061\u0071\u005a\u0021\u006f\u0072\u004b\u0060\u006a\u0063\u003b\u004d\u0050\u0058\u004e\u002d\u0045\u007e\u005e\u006b\u0069\u006e\u0021\u003f\u005e\u003d\u0063\u005d\u0044\u004c\u0035\u0058\u0039\u0020\u0044\u002f\u002f\u003e\u004e\u005a\u0027\u0059\u006b\u0035\u007c\u0039\u0036\u0062\u0032\u0068\u0062\u0041\u0030\u0078\u0065\u0061\u0028\u0029\u002a\u0074\u0029\u0077\u002c\u0050\u0045\u002e\u0023\u0035\u006d\u0037\u005e\u003e\u002d\u0027\u0062\u0051\u004b\u0020\u0058\u0072\u004d\u0079\u0022\u0041\u0025\u007a\u0078\u0024\u0020\u0030\u006f\u0073\u007a\u0038\u007b\u0024\u006d\u0073\u003f\u0030\u0063\u0022\u0021\u0025\u0031\u0068\u006d\u007a\u0047\u002b\u0025\u0065\u0078\u0045\u003f\u0036\u0045\u0024\u0047\u004e\u004a\u002f\u0025\u0045\u0038\u007a\u0058\u0060\u0042\u0022\u006e\u0071\u006b\u0045\u0042\u0026\u003d\u005b\u004a\u002f\u005d\u0053\u005e\u002f\u0032\u006f\u006b\u0031\u0052\u0065\u0067\u003a\u0073\u0025\u0041\u0046\u006b\u0025\u0067\u002f\u0044\u0044\u006e\u0025\u0047\u0024\u0025\u0068\u0066\u0065\u003f\u0055\u007e\u005e\u0060\u0067\u0025\u005a\u003b\u0044\u0041\u004c\u0058\u0078\u005d\u0029\u0066\u003e\u0026\u0043\u0073\u002c\u005a\u0037\u0041\u0054\u004f\u003d\u006d\u007d\u0024\u0065\u002f\u004a\u0056\u0048\u0061\u005d\u0031\u003c\u0053\u0068\u0042\u002d\u0059\u005e\u0077\u004d\u0074\u0062\u003a\u006c\u0065\u0072\u005a\u0077\u0062\u0034\u003f\u003c\u006b\u0052\u0061\u0062\u0071\u004b\u0043\u0034\u006a\u003f\u0031\u007b\u0079\u0028\u0046\u006c\u0073\u003e\u0021\u004c\u002e\u0071\u003d\u0064\u007b\u0023\u0041\u007d\u0040\u002d\u005a\u0064\u005f\u005b\u002b\u0070\u0059\u0043\u0047\u0060\u0064\u0077\u0038\u0030\u0037\u0044\u0039\u0027\u007c\u002e\u004f\u0020\u003e\u0049\u0047\u0074\u002f\u005d\u004d\u0055\u0034\u0058\u0045\u0051\u003f\u005e\u0050\u0073\u0058\u004d\u0065\u007d\u0020\u0078\u0076\u0041\u0041\u0070\u006e\u0032\u0058\u002c\u005c\u0028\u0029\u0062\u0042\u0047\u005b\u0066\u0060\u006d\u003b\u0069\u0041\u0060\u006e\u0042\u002b\u002d\u007d\u0044\u0027\u007b\u0071\u003a\u0039\u0037\u004d\u0051\u0032\u007d\u004c\u0041\u0046\u004b\u0051\u0073\u0031\u004b\u004b\u0060\u005f\u0037\u006d\u0071\u006e\u0032\u0062\u0034\u0040\u0065\u003b\u007d\u0047\u0041\u0066\u0078\u0023\u003f\u0038\u0053\u003d\u0040\u007b\u0058\u0051\u002d\u002c\u002c\u005a\u002c\u0077\u0057\u0048\u0065\u0052\u0036\u0071\u005c\u005f\u0044\u007e\u0059\u003c\u0020\u003b\u004d\u0025\u0054\u0050\u002e\u0067\u003b\u0055\u0053\u0068\u007a\u0048\u007a\u0063\u004a\u006d\u003f\u0034\u002d\u002e\u006f\u0048\u005d\u0022\u007c\u0034\u004f\u003f\u007b\u0079\u0076\u0067\u002b\u003b\u0020\u003d\u005b\u005b\u0038\u0071\u003c\u0056\u0039\u0039\u007b\u0073\u007e\u005e\u004e\u005a\u0075\u007a\u0062\u0054\u006e\u0065\u0022\u002f\u007e\u0055\u005e\u0045\u0038\u0034\u002a\u0078\u0070\u0062\u0048\u0053\u002b\u0071\u0044\u0066\u0054\u006d\u006e\u0041\u005a\u0069\u0030\u004a\u005d\u0074\u006e\u0079\u0067\u0044\u0052\u006f\u0055\u003d\u002a\u0038\u0020\u0079\u003f\u0031\u0055\u0069\u005d\u0038\u004e\u0029\u0049\u0023\u004e\u0021\u0035\u0033\u003a\u007d\u0074\u0062\u002f\u0057\u0036\u005b\u004e\u002c\u0032\u004a\u0022\u006d\u0046\u005a\u005d\u007e\u007d\u007a\u0027\u007a\u0040\u0073\u004e\u002f\u0034\u0060\u005b\u0020\u0027\u007b\u0038\u0039\u0036\u0069\u0053\u0050\u0059\u002e\u0037\u0044\u003d\u0068\u003d\u0050\u0071\u0039\u003c\u0074\u0042\u0073\u0063\u006c\u0042\u0048\u002e\u004b\u004e\u006c\u0053\u0027\u0065\u0054\u0040\u005a\u004f\u0063\u005f\u0048\u0070\u0026\u0025\u0051\u0061\u0065\u0072\u0067\u002a\u0037\u007d\u005e\u0067\u003f\u003e\u003a\u006c\u0035\u003f\u0055\u0071\u005e\u002f\u0056\u005f\u0041\u002d\u004d\u0074\u005a\u004c\u0034\u002a\u007e\u003b\u0029\u002d\u005f\u0045\u002e\u0041\u002a\u005b\u0035\u003f\u0061\u0073\u0060\u005a\u005b\u005f\u006d\u006b\u005e\u0053\u006a\u0058\u003e\u002f\u003d\u0053\u0067\u0048\u0063\u005b\u0072\u002b\u0026\u0036\u0070\u0066\u0060\u0031\u006b\u003f\u0057\u0021\u003c\u003e\u0037\u002a\u003b\u005d\u0035\u0034\u006a\u0049\u0032\u0026\u0045\u0034\u007b\u0061\u0054\u0044\u0027\u0076\u0035\u0037